// Simulador de la regla de Linux: se elige UNA sola clase (dueño, grupo u otros).
const usuarios = {
  ana:   { uid: 1001, grupos: [1001, 2001] },
  beto:  { uid: 1002, grupos: [1002, 2001] },
  carla: { uid: 1003, grupos: [1003] },
  root:  { uid: 0,    grupos: [0] },
};
const R = 4, W = 2, X = 1;

function puede(quien, archivo, quiere) {
  const u = usuarios[quien];
  if (u.uid === 0) return true;                       // root se salta la regla
  const digitos = [(archivo.modo >> 6) & 7, (archivo.modo >> 3) & 7, archivo.modo & 7];
  let clase;
  if (u.uid === archivo.uid) clase = digitos[0];      // 1) dueño
  else if (u.grupos.includes(archivo.gid)) clase = digitos[1];  // 2) grupo
  else clase = digitos[2];                            // 3) otros
  return (clase & quiere) === quiere;
}

const pedidos = { uid: 1001, gid: 2001, modo: 0o660 };
for (const q of ["ana", "beto", "carla", "root"]) {
  console.log(q.padEnd(6), "leer:", puede(q, pedidos, R), " escribir:", puede(q, pedidos, W));
}
const raro = { uid: 1001, gid: 2001, modo: 0o070 };   // el caso del dueño bloqueado
console.log("con 070 -> ana leer:", puede("ana", raro, R), " beto leer:", puede("beto", raro, R));
